new_method = '''    def _apply_role_continuation_mask(
        self,
        logits: torch.FloatTensor,
        partial: str,
        allowed_roles: set[str],
    ) -> torch.FloatTensor:
        \"\"\"Block grammar-valid tokens that can only continue toward disallowed roles.\"\"\"
        still_reachable = {r for r in allowed_roles if r.startswith(partial)}
        if not still_reachable:
            return logits

        all_matching = {r for r in self.spec.all_roles if r.startswith(partial)}
        if all_matching == still_reachable:
            return logits

        grammar_valid_mask = logits > self._GRAMMAR_MASK_THRESHOLD
        grammar_valid_ids = grammar_valid_mask.nonzero(as_tuple=True)[0].tolist()

        if len(grammar_valid_ids) > 500:
            return logits

        tokens_to_block = []
        tokens_allowed = []
        for tid in grammar_valid_ids:
            text = self._decode_token(tid)
            if not text:
                tokens_allowed.append(tid)
                continue
            extended = partial + text
            reachable_from_ext = any(
                r.startswith(extended) or extended.startswith(r)
                for r in still_reachable
            )
            if reachable_from_ext:
                tokens_allowed.append(tid)
            else:
                tokens_to_block.append(tid)

        if not tokens_to_block or not tokens_allowed:
            return logits

        logits[tokens_to_block] = float(\"-inf\")
        return logits'''

assert old_method in content, 'old method not found'
content = content.replace(old_method, new_method, 1)

with open('compiler/type_mask_processor.py', 'w') as f:
